-- 10-load-eval-dataset
-- GENERATED by scripts/generate_install_sql.py from evaluations/demo/demo_questions.yaml and *_demo_eval.yaml. Do not edit by hand.
-- Run from the repo root: snow sql -c <connection> --enable-templating NONE -f install/10-load-eval-dataset.sql

-- Question bank -> CORTEX_SENSE_DEMO.EVALS.EVAL_SOURCE_DEMO_FINANCE_VS_SENSE -> dataset CORTEX_SENSE_DEMO.EVALS.DEMO_FINANCE_VS_SENSE_V4 (the name comes from the eval configs).
-- A dataset can't be overwritten: after changing questions or ground truth, bump the
-- dataset_name suffix in all three *_demo_eval.yaml files and regenerate.

CREATE OR REPLACE TABLE CORTEX_SENSE_DEMO.EVALS.EVAL_SOURCE_DEMO_FINANCE_VS_SENSE (
  QUESTION_ID NUMBER, DEMO_ID VARCHAR, BUCKET VARCHAR, CONCEPT VARCHAR, INPUT_QUERY VARCHAR, GROUND_TRUTH VARIANT
);

INSERT INTO CORTEX_SENSE_DEMO.EVALS.EVAL_SOURCE_DEMO_FINANCE_VS_SENSE
SELECT 1, 'T01', 'tie', 'revenue', 'What are the top 10 games by lifetime revenue?', TO_VARIANT(OBJECT_CONSTRUCT('ground_truth_output', 'Top 10 titles by lifetime digital revenue: Horizon Zero Dawn ~$1.46M, Marvel''s Spider-Man ~$1.38M, God of War (2018) ~$1.38M, Spider-Man 2 ~$954K, GT7 ~$900K, God of War Ragnarok ~$900K, Ghost of Tsushima ~$780K, Gran Turismo Sport ~$764K, Helldivers 2 ~$700K, Gran Turismo 5 ~$690K. Values within +/-3% are acceptable; the order of the near-tied Spider-Man and God of War (2018), and of GT7 and God of War Ragnarok, may swap.'))
UNION ALL SELECT 2, 'T02', 'tie', 'portfolio revenue', 'What is our total lifetime portfolio revenue by franchise?', TO_VARIANT(OBJECT_CONSTRUCT('ground_truth_output', 'Total lifetime digital revenue is ~$19.23M. Top franchises: God of War ~$3.43M (7 titles), Marvel''s Spider-Man ~$2.99M (3), Gran Turismo ~$2.65M (4), Horizon ~$2.14M (5), MLB The Show ~$1.20M (10), The Last of Us ~$1.10M (3), Ghost of Tsushima ~$780K (1), Helldivers ~$700K (1). About $230K belongs to two titles with no catalog franchise mapping. Values within +/-3% are acceptable.'))
UNION ALL SELECT 3, 'S01', 'sense_only', 'genre', 'What are the top 5 genres by lifetime revenue?', TO_VARIANT(OBJECT_CONSTRUCT('ground_truth_output', 'Using full genre classification matches (a game can match several genres, so totals overlap and must not be read as shares of total revenue), the top 5 genres by lifetime revenue are: ActionRPG ~$13.24M (42 games), DynamicAdventure ~$12.43M (33), Shooter ~$6.40M (27), TPS ~$6.20M (18), Gore ~$6.08M (11). Values within +/-3% are acceptable. The response must give genre-level revenue, not franchise or publisher revenue.'))
UNION ALL SELECT 4, 'S02', 'sense_only', 'awards', 'How does lifetime revenue of award-winning games compare with games that never won an award?', TO_VARIANT(OBJECT_CONSTRUCT('ground_truth_output', '9 award-winning games (at least one win, nominations excluded) earned ~$6.64M total, an average of ~$738K per game. The 76 games that never won earned ~$12.36M total, an average of ~$163K per game. Award winners average roughly 4.5x more lifetime revenue per game. About $230K from two titles with no catalog mapping is excluded or reported separately. Values within +/-3% are acceptable. The never-won group may be split into sub-groups (for example nominated-only, about 8 games and ~$4.79M, and no award recognition, about 68 games and ~$7.57M) without stating the combined figure, as long as the sub-groups add up to about 76 games and ~$12.36M. Treat such a split as fully correct.'))
UNION ALL SELECT 5, 'S03', 'sense_only', 'monetization', 'What is the total lifetime revenue by monetization model?', TO_VARIANT(OBJECT_CONSTRUCT('ground_truth_output', 'Lifetime revenue of titles using each monetization model (titles can use several models, so totals overlap): premium ~$19.23M (87 titles), dlc ~$7.25M (11), microtransactions ~$3.64M (16), loot_boxes ~$1.20M (10), battle_pass ~$760K (2), subscription ~$4K (1). Values within +/-3% are acceptable. The response should note that models overlap.'))
UNION ALL SELECT 6, 'S04', 'sense_only', 'engines', 'Which game engines power the most lifetime revenue? Show the top 5.', TO_VARIANT(OBJECT_CONSTRUCT('ground_truth_output', 'Top 5 engines by lifetime revenue of the games built on them: Santa_Monica_Engine ~$3.42M (6 games), Insomniac_Engine ~$3.36M (5), Polyphony_Engine ~$2.65M (4), Decima ~$2.53M (5), Naughty_Dog_Engine ~$1.41M (4). Values within +/-3% are acceptable.'))
UNION ALL SELECT 7, 'S05', 'sense_only', 'accessibility', 'Which of the top 5 highest-revenue games have the fewest accessibility features, and how many are they missing?', TO_VARIANT(OBJECT_CONSTRUCT('ground_truth_output', 'Of the 10 tracked accessibility features, among the top 5 revenue games: GT7 and Horizon Zero Dawn are each missing 7 (fewest features), God of War (2018) is missing 6, and Marvel''s Spider-Man and Spider-Man 2 are each missing 4. Counts must match exactly.'))
UNION ALL SELECT 8, 'S06', 'sense_only', 'genre whitespace', 'How many genre combinations are whitespace, underserved, or served in the market?', TO_VARIANT(OBJECT_CONSTRUCT('ground_truth_output', 'Of the logically valid genre combinations: 536 are WHITESPACE (no games), 7 are UNDERSERVED (1 to 2 games) and 16 are SERVED. Counts must match exactly. The response may note that whitespace measures low supply, not proven demand.'))
UNION ALL SELECT 9, 'S07', 'sense_only', 'portfolio strategy and cannibalization', 'Under our FY2027 portfolio strategy, which Growth franchise has a HIGH audience overlap with a Core franchise, and what should we do about it?', TO_VARIANT(OBJECT_CONSTRUCT('ground_truth_output', 'Per the FY2027 strategy memo, Marvel''s Spider-Man is a Growth franchise and God of War is a Core franchise. Their games have HIGH audience overlap: God of War (2018) / Marvel''s Spider-Man ~0.71, God of War Ragnarok / Marvel''s Spider-Man: Miles Morales ~0.71, God of War Ragnarok / Marvel''s Spider-Man ~0.62, and God of War (2018) / Miles Morales ~0.62. Under strategic priority 1 (reduce internal cannibalization) the Growth franchise, Spider-Man, must reposition (differentiate its audience and positioning, avoid God of War launch windows) while God of War, the Core franchise, keeps its course. Mentioning the Spider-Man / Bloodborne HIGH pair (~0.72) is acceptable but it is Growth vs Growth, not a Core threat. Overlap values within +/-0.02 are acceptable.'))
UNION ALL SELECT 10, 'S08', 'sense_only', 'EU regulatory risk (live-service, age ratings)', 'Under our EU loot box regulatory brief, which of our live-service games carry EU regulatory risk, what tier is each, and what mitigations are required?', TO_VARIANT(OBJECT_CONSTRUCT('ground_truth_output', 'Sixteen games are live-service (online required plus recurring monetization). HIGH: Helldivers 2, because it is rated PEGI 18 (PEGI; a PEGI 18 rating combined with monetization draws regulator and media attention). Required HIGH mitigations: legal review before any EU content update, disable paid random rewards in Belgium, and publish drop rates. No live- service game meets the loot-box-on-mobile condition: MLB The Show 17 through 26 use loot boxes but none is on Android or Apple. ELEVATED (live-service and rated below PEGI 18, so minors are in the audience): Destruction AllStars (PEGI 12), Gran Turismo 7 and Gran Turismo Sport (PEGI 3), and MLB The Show 17 through 26 (PEGI 3). This exposure relates to the EU Digital Services Act and EU consumer protection rules on virtual-currency pricing; the MLB The Show titles also carry loot boxes, which Belgium treats as gambling and the Netherlands scrutinizes. Required ELEVATED mitigations: show real-money prices next to virtual currency, turn on spending limits and parental controls by default, avoid time-limited pressure offers aimed at under-18 accounts, and review annually. Firewall Zero Hour and Marathon are live- service but have no PEGI rating in the data, so they are not HIGH and their ELEVATED status cannot be confirmed; the answer should flag this gap. The answer should note the brief is a simplified internal summary, not legal advice.'));

CALL SYSTEM$CREATE_EVALUATION_DATASET('Cortex Agent', 'CORTEX_SENSE_DEMO.EVALS.EVAL_SOURCE_DEMO_FINANCE_VS_SENSE', 'CORTEX_SENSE_DEMO.EVALS.DEMO_FINANCE_VS_SENSE_V4',
  OBJECT_CONSTRUCT('query_text', 'INPUT_QUERY', 'expected_tools', 'GROUND_TRUTH'));

